package kz.bekzat.jwt.dao;
import kz.bekzat.jwt.db.DatabaseConnection; import kz.bekzat.jwt.model.SecurityEvent; import org.springframework.stereotype.Repository; import java.sql.*; import java.time.Instant; import java.util.*;
@Repository public class SecurityEventDao { private final DatabaseConnection db; public SecurityEventDao(DatabaseConnection db){this.db=db;} public void save(SecurityEvent e){try(Connection c=db.open();PreparedStatement p=c.prepareStatement("INSERT INTO security_events(event_type,username,description,ip_address,timestamp) VALUES(?,?,?,?,?)")){p.setString(1,e.eventType());p.setString(2,e.username());p.setString(3,e.description());p.setString(4,e.ipAddress());p.setString(5,e.timestamp().toString());p.executeUpdate();}catch(SQLException x){throw new IllegalStateException(x);}} public List<SecurityEvent> findAll(){List<SecurityEvent> a=new ArrayList<>();try(Connection c=db.open();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT * FROM security_events ORDER BY timestamp DESC")){while(r.next())a.add(new SecurityEvent(r.getString("event_type"),r.getString("username"),r.getString("description"),r.getString("ip_address"),Instant.parse(r.getString("timestamp"))));return a;}catch(SQLException e){throw new IllegalStateException(e);}} }
